fn pow10(k: i32) -> i32 {
    let mut p: i32 = 1;
    let mut i: i32 = 0;
    while i < k {
        p = p * 10;
        i = i + 1;
    }
    p
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x101010);
    let cw: i32 = 56;
    let x0: i32 = w / 2 - cw * 3;
    let y: i32 = h / 2 - 32;
    let mut k: i32 = 0;
    while k < 6 {
        let d: i32 = (t / pow10(5 - k)) % 10;
        host::display::fill_rect(x0 + k * cw, y, cw - 6, 64, 0x000000);
        host::display::fill_rect(x0 + k * cw + 2, y + 2, cw - 10, 60, 0x202028);
        host::display::draw_number(x0 + k * cw + 12, y + 12, d, 0xffe080, 5);
        k = k + 1;
    }
    host::display::draw_string(x0, y + 78, "TOTAL FRAMES", 0x808080, 1);
    host::display::present();
}
